using System;using System.IO;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
public static class NWEditor {static EditorWindow view;static bool started;static double deadline;static string root;public static void RunPerformance(){Environment.SetEnvironmentVariable("NW_MODE","performance");Run();}public static void RunDrop(){Environment.SetEnvironmentVariable("NW_MODE","drop");Run();}public static void RunBoundary(){Environment.SetEnvironmentVariable("NW_MODE","boundary");Run();}public static void RunStorage(){Environment.SetEnvironmentVariable("NW_MODE","storage");Run();}public static void RunScythe(){Environment.SetEnvironmentVariable("NW_MODE","scythe");Run();}public static void RunHeavy(){Environment.SetEnvironmentVariable("NW_MODE","heavy");Run();}public static void Run(){root=ValidationStorage.Root(Environment.GetCommandLineArgs(),true);deadline=EditorApplication.timeSinceStartup+600;view=UI01Before.Size(1280,720);EditorSceneManager.playModeStartScene=null;EditorSceneManager.OpenScene(GameEntry.TitlePath);EditorApplication.update+=Tick;EditorApplication.EnterPlaymode();}static void Tick(){try{EditorApplication.QueuePlayerLoopUpdate();view?.Repaint();if(EditorApplication.timeSinceStartup>deadline)throw new Exception("NW bounded deadline");if(!EditorApplication.isPlaying)return;if(!started){if(UnityEngine.SceneManagement.SceneManager.GetActiveScene().path!=GameEntry.TitlePath)return;if(Environment.GetEnvironmentVariable("NW_MODE")!="storage"&&Environment.GetEnvironmentVariable("NW_MODE")!="drop")CP05Training.StartIsolated();var go=new GameObject("NW Editor probe");UnityEngine.Object.DontDestroyOnLoad(go);go.AddComponent<NWProbe>();started=true;}if(NWProbe.Done){EditorApplication.update-=Tick;EditorApplication.Exit(NWProbe.Code);}}catch(Exception e){File.WriteAllText(root+"/exception.txt",e.ToString());EditorApplication.update-=Tick;EditorApplication.Exit(1);}}}
